class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(arr):
    if not arr or arr[0] is None:
        return None
    root = TreeNode(arr[0])
    queue = [root]
    i = 1
    while i < len(arr) and queue:
        node = queue.pop(0)
        if i < len(arr):
            left_val = arr[i]
            i += 1
            if left_val is not None:
                node.left = TreeNode(left_val)
                queue.append(node.left)
        if i < len(arr):
            right_val = arr[i]
            i += 1
            if right_val is not None:
                node.right = TreeNode(right_val)
                queue.append(node.right)
    return root


def rob(root_arr):
    root = build_tree(root_arr)

    def dfs(node):
        if node is None:
            return (0, 0)
        left_rob, left_not = dfs(node.left)
        right_rob, right_not = dfs(node.right)
        rob_this = node.val + left_not + right_not
        not_rob_this = max(left_rob, left_not) + max(right_rob, right_not)
        return (rob_this, not_rob_this)

    rob_root, not_rob_root = dfs(root)
    return max(rob_root, not_rob_root)

